"""Export uncertainty evidence, residual CSV, camera ranges, report and delivery manifest.
Call export_profile_evidence(namespace) after uncertainty.main(). Uses only standard
Python + numpy. All outputs remain inside this folder.
"""
import os,json,csv,hashlib,math
import numpy as np
O=os.path.dirname(os.path.abspath(__file__))
def export_profile_evidence(U):
 accepted=[a.tolist() for a in U['accepted']];json.dump({'acceptance':'global native scalar-coordinate/edge RMS <= baseline+2px','solutions':accepted},open(O+'/accepted-profile-solutions.json','w'),indent=2)
 cams=json.load(open(O+'/cameras.json'));N=U['N']
 for i,k in enumerate(N['keys']):
  values=[]
  for a in U['accepted']:
   M,R,t,f=N['camera'](a,i);C=-R.T@t;values.append((C,f,f*36/N['photos'][k]['size_px'][0],1/a[N['nshape']+7*i+3],math.degrees(a[N['nshape']+7*i+1])))
  cams['photos'][k]['uncertainty']={'method':'range among accepted joint nonlinear profile samples; conditional, not a confidence interval','position_m_axis_aligned_range':[[float(min(a[0][j] for a in values)),float(max(a[0][j] for a in values))] for j in range(3)],'focal_px_range':[float(min(a[1] for a in values)),float(max(a[1] for a in values))],'36mm_equivalent_focal_mm_range':[float(min(a[2] for a in values)),float(max(a[2] for a in values))],'optical_axis_distance_m_range':[float(min(a[3] for a in values)),float(max(a[3] for a in values))],'optical_axis_elevation_degrees_range':[float(min(a[4] for a in values)),float(max(a[4] for a in values))]}
  inv=float(U['x'][N['nshape']+7*i+3]);cams['photos'][k]['distance_focal_identifiability']='Orthographic limit reached: 5000m numerical depth cap; this is not a measured physical camera position or lens.' if inv<=.000201 else 'Conditional on principal point at image centre and zero distortion; distance and focal length covary.'
 json.dump(cams,open(O+'/cameras.json','w'),indent=2)

def write_report():
 p=json.load(open(O+'/proportions.json'));d=p['dimensions'];rs=json.load(open(O+'/residual-summary.json'));fixed=json.load(open(O+'/current-spec-comparison.json'));cams=json.load(open(O+'/cameras.json'))['photos'];diag=json.load(open(O+'/profile-diagnostics.json'))
 rows=json.load(open(O+'/residuals.json'))
 with open(O+'/residuals.csv','w',newline='') as f:
  w=csv.writer(f);w.writerow(['photo','name','kind','observed_x','observed_y','predicted_x','predicted_y','euclidean_or_normal_error_px','annotation_sigma_px'])
  for a in rows:w.writerow([a['photo'],a['name'],a['kind'],*a['observed_px'],*a.get('predicted_px',a.get('predicted_nearest_px')),a['residual_px'],a['sigma_px']])
 labels=[('overall_length','Overall length',4.58),('body_width','Maximum body width',2.),('roof_height','Roof height',1.15),('wheelbase','Wheelbase',2.95),('front_overhang','Front overhang',.875),('rear_overhang','Rear overhang',.755),('front_track','Front track',1.68),('rear_track','Rear track',1.68),('tyre_diameter','Tyre diameter',.72),('wheel_width','Common wheel width',.30),('hub_height','Hub height',.36),('ground_clearance','Sill ground clearance',None),('nose_tip_height','Upper nose leading edge height',None),('tail_top_height','Tail top, wing closed',None),('windscreen_base_y','Windscreen base Y from axle midpoint',None),('windscreen_base_aft_front_axle','Windscreen base aft of front axle',None),('windscreen_base_aft_nose','Windscreen base aft of nose',None),('windscreen_base_height','Windscreen base height',None),('body_top_over_front_wheel','Front crown / arch lip height',.834)]
 lines=['# Five-photo proportions audit — provisional, not recovered real-car dimensions','',
 'One shared bilateral cage and four circular wheel cylinders were fitted jointly with five perspective cameras. The best recorded fit is **4.409 m long, 2.197 m at the rear body, 1.203 m high, with a 2.839 m wheelbase**, conditional on 0.720 m tyres. **It is not accurate enough to adopt as a real-car spec.** The residuals and broad tolerance ranges leave the proportions weakly identified.','',
 '| Dimension | Current (m) | Joint fit (m) | / wheelbase | Sampled +2 px support (m) |','|---|---:|---:|---:|---|']
 for k,label,current in labels:
  a=d[k];iv=a['uncertainty']['metres'];lines.append(f"| {label} | {current:.3f}"+f" | {a['metres']:.3f} | {a['ratio_to_wheelbase']:.4f} | {iv[0]:.3f}–{iv[1]:.3f} |" if current is not None else f"| {label} | — | {a['metres']:.3f} | {a['ratio_to_wheelbase']:.4f} | {iv[0]:.3f}–{iv[1]:.3f} |")
 lines += ['', 'Current overhangs use the v7 envelope (-2.35 to +2.23 m) and hub positions; the original prompt specified only their sum. The 0.834 m crown is the v7 mesh measurement in its report, not a nominal size requirement. The fitted front body width is '+f"{d['front_body_width']['metres']:.3f} m; maximum width is the separate rear arch-lip station. Mirrors are excluded. The roof and tail omit the deployed wing and open doors.",'',
 '**Residuals in native source pixels** (point Euclidean distance; wheel-edge nearest ellipse distance):','', '| Photo | Observations | RMS (px) | Median (px) | Worst (px) |','|---|---:|---:|---:|---:|']
 for k,a in rs.items():lines.append(f"| {k} | {a['landmarks_and_edge_samples']} | {a['rms_euclidean_or_edge_distance_px']:.2f} | {a['median_px']:.2f} | {a['max_px']:.2f} |")
 lines += ['', f"The scalar-coordinate RMS used by the tolerance profiles is {diag['baseline_raw_scalar_rms_px']:.3f} px; acceptance is ≤{diag['limit_px']:.3f} px. This differs from the per-observation RMS above because a point contributes x and y coordinates and an edge contributes one Sampson normal-distance approximation. `residuals.json` and `residuals.csv` contain every measured residual. No landmark was silently dropped as an outlier.",'',
 '**Confidence and limits.** The tabulated ranges are extrema among accepted nonlinear profile samples, with all other proportions and cameras refitted. They are feasible sampled support, not exhaustive bounds or statistical confidence intervals. They do not include incorrect landmark identity, cage simplification, lens distortion, tyre deformation, different front/rear tyre diameters or wheel widths, suspension movement, motion blur, cropped principal points, or reveal-image synthesis/retouching. The cage does not impose a hard wheel/body enclosure constraint; protrusion at a simplified width station is another model limitation. The wheel ellipses in `landmarks.json` are approximate reconstructions of the observed arcs; hidden or edge-on rims are explicitly unobserved. Hub height 0.360 m follows mathematically from the circular tyre/flat-ground convention and is not independently measured. All metric numbers scale linearly with assumed tyre diameter. Wheelbase ratios are scale-free within the model.','',
 '**Camera evidence.** Side optical-axis elevation is '+f"{cams['05-hero']['elevation_degrees']:.2f}°, but its distance/focal pair reaches the 5000 m numerical orthographic limit. Those camera values reproduce a projection; they do not identify the actual lens or camera location. Other cameras also have substantial covariance with dimensions. NumPy projections were checked independently against Blender camera projections; worst disagreement was {max(a['blender_projection_check_max_px'] for a in cams.values()):.3f} px. No production mesh supplied the fitted landmarks.",'',
 '**Comparison with the current spec.** Fixing current length/overhangs, body widths, height, wheelbase, tracks and wheel width while refitting all cameras and feature positions gives '+f"{fixed['fixed_scalar_rms_px']:.3f} px scalar RMS versus {fixed['free_scalar_rms_px']:.3f} px for the free fit. The side camera is {fixed['side_optical_axis_elevation_degrees']:.2f}°, so the previous 14.87° camera is not required by those dimensions in this cage. The free proportions improve the objective, but this does not establish that the old dimensions caused pass 7's silhouette problem. Residuals remain large relative to the annotated edge/feature uncertainties; the +2 px allowance is a tolerance for profiling, not an absolute fit target.",'',
 '**Sanity check against the supplied hypercar ranges.** Length 4.409 m, height 1.203 m and tyres 0.720 m fall within the supplied 4.2–4.7 m, 1.10–1.25 m and 0.68–0.76 m ranges. Maximum rear width 2.197 m is 0.097 m above the supplied 2.10 m upper bound; front width 1.925 m is 0.025 m below its 1.95 m lower bound. The rear result comes from the near arch lip and wheel perspective in stage shots, not a calibrated transverse view. Its uncertainty and possible correspondence/model bias are too large to infer an unusually wide real car. Those supplied sanity ranges were not used as optimisation priors.','',
 '**Recommendation.** Keep the current size requirements provisional; do not replace them with these point estimates or cut the front crowns by 0.25–0.30 m. A working trial could use 4.41 m length, 2.20 m maximum rear width (1.93 m front), 1.20 m height and 2.84 m wheelbase, but it must remain labelled unverified. The defensible change now is to remove the inherited 15° side-camera requirement and reopen joint camera/feature fitting. A tighter spec needs independently identified corresponding features, calibrated image intrinsics or a published/measured dimension beyond the assumed tyre diameter.','',
 '**Files and reproduction.** `landmarks.json`, `proportions.json`, `cameras.json`, the five native `renders/fit-*.png`, annotated source copies, `Proportions.blend`, all fitting scripts, profile diagnostics and leave-one-photo-out sensitivity are included. Cyan is the cage, green the wheels, yellow the pixel picks and red the residuals. Faint dashed wheel edges are occluded construction. `run_all.py` reproduces the workflow in Blender Python using bundled numpy. `measure.py` is the editable source of manual picks. Source images 01/02 were measured at 2200×1040 / 2560×1035, not the smaller sizes used in earlier camera records. Photos 06–08 are excluded from fitting because this run uses the five requested ground-view photographs.','',
 '**Evidence status:** photo landmarks and projected overlays visually inspected; Blender/NumPy projection agreement checked. Real dimensions, camera calibration and all in-game claims remain unverified. No production meshes or prior pass files were changed.']
 open(O+'/report.md','w').write('\n'.join(lines)+'\n')
 # Include primary files and hashes for deterministic review; timings/Blender files are not deterministic.
 manifest={}
 for file in ['landmarks.json','proportions.json','cameras.json','residuals.json','residuals.csv','report.md','Proportions.blend']+[f'renders/fit-{k}.png' for k in rs]:
  path=O+'/'+file;manifest[file]={'bytes':os.path.getsize(path),'sha256':hashlib.sha256(open(path,'rb').read()).hexdigest()}
 json.dump(manifest,open(O+'/delivery-manifest.json','w'),indent=2)
 return {'written':'report.md, residuals.csv, delivery-manifest.json','total_observations':len(rows)}
if __name__=='__main__':write_report()
